RESERVED = {0,1,2,3,19,29,38,39,48,49,61,69,71,87,101,116,117,118,119,120,121,122,123,124,125,126,127,128,129,164,165,166,167,168,169,170,171,172,173,174,175,176,177,178,179,180,181,182,183,184,185,186,187,188,189,190,207,208,209,210,211,212,213,214,215,216,217,218,219,220,226,227,228,229,230,231,232,233,234,235,236,237,238,239,240,241,242,243,244,245,246,247,248,249,257,258,259,268,273,274,311,323,324,325,326,327,328,329,330,331,332,333,334,335,336,337,338,339,340,341,342,343,344,345,346,347,348,349,359,365,384,392,394,410,411,412,422,427,428,429,438,439,446,447,448,449,451,463,464,466,467,468,469,471,472,473,474,477,478,498}
FLAGS = {
479:('Главный зал Истинной лаборатории посещён','Код создания truelab_hub ставит 1. Пока 0, в лифте и первом коридоре применяется переходный вариант декоративной рамки 3.5. Не питание лаборатории и не собранные ключи.',{0:'Главный зал ещё не посещён',1:'Главный зал посещён'},'Дойти до центрального зала Истинной лаборатории.'),
480:('Затемнение спрайта героя в Истинной лаборатории','Двери лаборатории ставят 1; создание героя затемняет цвет через merge_color(gray,white,0.3). Выход лифтом к замку обнуляет. Это визуальное состояние комнаты, не сюжетный страх.',{0:'Обычная яркость героя',1:'Затемнённый герой'},'Войти в лабораторные коридоры; при выходе снимается сценарием.'),
481:('Красный ключ Истинной лаборатории','1 — после события у раковин ключ оставлен; 2 — поднят на связку; 3 — вставлен в красный переключатель. 0 — начальное состояние. Положение оставленного ключа — flag[487], состояние раковин — 486.',{0:'Ключ ещё не появился',1:'Ключ оставлен у раковины',2:'Ключ на связке',3:'Красный переключатель включён'},'Пройти событие с Памятоголовыми у раковин, подобрать ключ и вставить в красный слот.'),
482:('Синий ключ Истинной лаборатории','После холодильников и боя ставится 1, вызывается временный сейв: ключ лежит на полу. Подбор даёт 2 и убирает объект; синий переключатель переводит 2→3.',{0:'Событие холодильников не закончено',1:'Ключ лежит на полу',2:'Ключ на связке',3:'Синий переключатель включён'},'Завершить встречу у холодильников, взять синий ключ и использовать его в синем слоте.'),
483:('Зелёный ключ Истинной лаборатории','Событие шторы ставит 1 и рисует ключ. Повторное взаимодействие забирает его (2), зелёный переключатель использует 2→3. 1 без второго взаимодействия ещё не означает владение ключом.',{0:'Штора не открыта',1:'Ключ обнаружен',2:'Ключ на связке',3:'Зелёный переключатель включён'},'Открыть штору, отдельно подобрать ключ и вставить в зелёный слот.'),
484:('Жёлтый ключ Истинной лаборатории','Осмотр подозрительной кровати раскрывает ключ (1), следующий осмотр кладёт на связку (2), жёлтый слот принимает его и пишет 3. Не обычный предмет инвентаря.',{0:'Ключ скрыт под покрывалом',1:'Покрывало отодвинуто',2:'Ключ на связке',3:'Жёлтый переключатель включён'},'Осмотреть кровать до получения ключа, затем активировать жёлтый переключатель.'),
485:('Финальная сцена питания лаборатории завершена','Конец lab_powerswitch пишет 1 вместе с 493=12,454=1 и plot не ниже 201. Мониторы и записи после этого выключены. Это завершение сцены, в отличие от самого нажатия 491.',{0:'Лабораторная сцена ещё не закончена',1:'Сцена закончена, мониторы выключены'},'Собрать цветные ключи, включить питание и досмотреть объяснение Альфис.'),
486:('Счётчик включений раковин лаборатории','Открытие крана увеличивает число; 2 имеет особую обработку события/ключа. Вступление встречи пишет 10; при 13 есть специальная реплика о любви мыть руки. Это не количество полученных ключей.',{0:'Краны ещё не включались',2:'Особая фаза события раковин',10:'Вступление встречи запущено',13:'Реплика о мытье рук'},'Включать краны в помещении красного ключа. Связан с 481 и 487.'),
487:('У какой раковины оставлен красный ключ','После появления ключа определяется X героя: <75 →1, <110 →2, иначе 3. Соответствующая раковина показывает ключ. Подбор сбрасывает 0 и ставит 481=2.',{0:'На раковинах ключа нет',1:'Левая раковина',2:'Средняя раковина',3:'Правая раковина'},'Завершить событие раковин; позиция героя в момент события определяет место ключа.'),
488:('Встреча у лабораторного восклицательного знака пройдена','После завершения obj_amalgam_exc пишет 1 и делает scr_tempsave; при повторном создании удаляется. Не общий флаг победы над всеми амальгамами.',{0:'Встреча доступна',1:'Не повторять встречу'},'Завершить событие с Птицей Жнецом у восклицательного знака.'),
489:('Ложная точка сохранения разоблачена','Финал obj_amalgam_save вызывает scr_tempsave, затем пишет 1 и удаляет событие. Порядок важен: временный файл может законно ещё содержать 0, пока в памяти уже 1. При >0 объект не создаётся.',{0:'Ложная звезда ещё доступна',1:'Встреча пройдена'},'Взаимодействовать с ложной звездой и завершить бой с Лимонным Хлебом.'),
490:('Вентиляция лаборатории включена и событие Эндогении снято','Нажатие вентилятора ставит 1, а финал встречи также пишет 1 и временно сохраняет. При 1 вентилятор вращается, туман прозрачен, dogevent не создаётся. Это совмещённая отметка сцены, не число поглаживаний.',{0:'Туман/событие ещё активны',1:'Вентиляция включена, повторное событие снято'},'Включить настенный переключатель и пройти событие Эндогении.'),
491:('Нажата кнопка питания лабораторного лифта','Выбор «Да» пишет 1 и запускает lab_powerswitch.con=5. При 1 текст сообщает, что питание включено. Окончание длинной сцены отдельно фиксирует 485 и 493.',{0:'Кнопка ещё не нажата',1:'Питание включено, сцена запущена'},'Дойти до выключателя после четырёх цветных ключей и подтвердить включение.'),
492:('Альфис ушла и её двери временно закрыты','После сопровождения в конце Хотленда пишет 1 и plot=199. Двери лаборатории при 1 закрываются. Финал свидания и последующий звонок снимают 0 и продвигают 493. Код story_engager также содержит необычную проверку >=12, но обычные показанные присваивания здесь 0/1 — не путать с 493.',{0:'Этой блокировки дверей нет',1:'Двери после ухода Альфис заблокированы'},'Пройти сопровождение Альфис; открыть следующую ветку через письмо и свидание.'),
494:('Утрата письма Андайн и выдача замены EX','Выбросить обычное письмо 56 — значение 1. Андайн при 1 или 2 выдаёт предмет 57, если есть место, и пишет 3. Сам флаг не заменяет инвентарь; повторно выданное EX нельзя выбросить обычным способом.',{0:'Обычное письмо не выброшено',1:'Письмо выброшено',2:'Состояние, также допускающее замену',3:'Письмо EX выдано'},'Выбросить первое письмо и попросить Андайн выдать ещё одно.'),
495:('Запас автомата чипсов в Истинной лаборатории','При <8 можно купить чипсы за 25 G; успешная выдача увеличивает число на 1. При 8 автомат исчерпан. Если >0, Альфис объясняет поведение амальгам запахом чипсов.',{0:'Куплено 0 из 8',1:'Куплена одна пачка',8:'Автомат пуст'},'Покупать чипсы при свободном слоте и достаточных G.'),
496:('Сцена Онионсана в Водопадье','0 — первое появление; 1–7 — последовательные позиции диалога по ходу комнаты, определяют возобновление сцены. Значение −1 отключает обычную последовательность после отказа или маршрутного условия; 6 фиксирует один из поздних положительных ответов.',{-1:'Обычная сцена отключена',0:'Первое появление',1:'Первая остановка пройдена',2:'Вторая остановка',6:'Поздний положительный ответ',7:'Поздняя фаза сцены'},'Проходить длинную комнату с Онионсаном и отвечать ему; установка номера не перемещает актёров автоматически.'),
497:('Ключи комнаты и мастерской Санса','Санс за последовательность паролей даёт 1 — ключ от спальни. Первый вход запускает шутку с дорожкой и поднимает до 2. Поиск в ящике даёт серебряный ключ и 3. Отдельные ключи не занимают обычный инвентарь.',{0:'Ключей нет',1:'Спальня открыта, первая шутка впереди',2:'Шутка спальни пройдена',3:'Серебряный ключ мастерской взят'},'Получить пароль через повторные загрузки суда Санса, войти в его спальню и осмотреть ящик.'),
499:('Первая инициализация финальных титров состоялась','При 0 создание castroll задаёт cast_type=0 и пишет 1. Это защита повторной инициализации списка титров, не «игра пройдена» и не набор жёлтых имён.',{0:'Титры ещё не инициализированы',1:'Инициализация была'},'Дойти до финальных титров.'),
500:('Вместо смерти — восстановление души в бою Азриэля','При 1 heartdefeated пропускает обычный game over, увеличивает 502 и запускает восстановление души. Бой Азриэля включает 1, Мэд Мью Мью явно сбрасывает 0. Не универсальное безопасное бессмертие: обработчик ждёт контекст Азриэля.',{0:'Обычная смерть',1:'Сценарное восстановление души'},'Начать финальный бой Азриэля. Не включать вне него.'),
501:('Фаза SAVE в финальном бою Азриэля','При >0 кнопка ACT заменена SAVE; после достижения условий спасения друзей минимум 2; переход панелей записывает 3, меняет поведение атак и диалоги. Это не вся сцена: требуются боевая группа, объекты и 505–508.',{0:'До открытия SAVE',1:'SAVE доступна',2:'Фаза спасения друзей',3:'Последний переход финала'},'Пережить атаки Азриэля и использовать SAVE в сюжетной последовательности.'),
502:('Сколько раз душа восстанавливалась у Азриэля','При создании heartdefeated с 500=1 увеличивается. После первой попытки меняются анимация восстановления, затемнение и вид Азриэля. Не общий счётчик всех смертей прохождения.',{0:'Восстановлений не было',1:'Первое восстановление',2:'Повторные восстановления'},'Потерять HP в бою Азриэля и восстановить душу.'),
503:('Последняя мечта уже использовалась','Предмет 55 ставит 1 при использовании. При повторе текст сокращён до «Мечта сбылась»; само использование лечит через scr_recoitem(17) и удаляет предмет.',{0:'Полный текст первого использования',1:'Короткий повторный текст'},'Использовать Последнюю мечту. Запись флага не выдаёт и не расходует её.'),
504:('Самый дальний ход первой фазы Азриэля','Сохраняет максимум turns. Повторное создание босса начинает с max(0,504−3), а старые ходы могут иметь сокращённые реплики. Это checkpoint боевого прогресса, не время в тиках.',{0:'Начало боя',3:'Повтор всё ещё с начала',4:'Повтор с хода 1'},'Продвигаться по ходам первой фазы боя Азриэля.'),
505:('Воспоминание Андайн спасено внутри Азриэля','Финал её встречи пишет 1 и возвращает к группе 256. В меню SAVE её имя меняется, сумма 505–508 участвует в переходе финальной фазы. Это не обычная дружба с Андайн.',{0:'Воспоминание не спасено',1:'Андайн вспомнила'},'Выбрать Андайн в SAVE и выполнить подходящие действия в её встрече.'),
506:('Воспоминание Альфис спасено внутри Азриэля','После завершения её встречи записывает 1 и возвращает в финальный бой. Входит в сумму четырёх спасённых групп, а не в флаг обычного свидания.',{0:'Воспоминание не спасено',1:'Альфис вспомнила'},'Выбрать Альфис в SAVE и пройти её сцену воспоминания.'),
507:('Воспоминание Папируса и Санса спасено','Один общий флаг на двух братьев: финал встречи ripoff_papyrus пишет 1. Оба пункта меню отмечаются вместе; не нужно искать отдельный флаг Санса.',{0:'Братья не вспомнили',1:'Воспоминание братьев спасено'},'Выбрать братьев в SAVE и завершить совместную сцену.'),
508:('Воспоминание Ториэль и Азгора спасено','Общий флаг родительской пары. Финал ripoff_toriel ставит 1 и возвращает к Азриэлю. Вместе с 505–507 заполняет четыре требуемые группы воспоминаний.',{0:'Пара не вспомнила',1:'Воспоминание Ториэль и Азгора спасено'},'Выбрать Ториэль/Азгора в SAVE и завершить сцену.'),
511:('Повторные разговоры с Азриэлем у цветочной клумбы','Счётчик бесед в эпилоге Руин. 1 — просит оставить его, 2 — не хочет разбивать сердца, 3 — замечает желание составить компанию; 4–7 — следующие части признания; >=8 — последний повторный ответ. После обращения +1.',{0:'Первый разговор',1:'Просьба оставить одного',2:'Не хочет разбивать сердца',3:'Компания Фриск',4:'Продолжение признания',5:'Продолжение признания',6:'Продолжение признания',7:'Заключительная часть',8:'Повторный ответ'},'После истинного финала вернуться к начальной клумбе в Руинах и многократно поговорить с Азриэлем.'),
403:('Дорогая покупка на паучьей распродаже','Покупка одного из паучьих товаров за 9999 G пишет 1 и увеличивает сумму пожертвований flag[59]. Сам флаг не выдаёт товар и не списывает деньги; исход Маффет также использует другие сведения о паучьей помощи.',{0:'Дорогой покупки нет',1:'Товар за 9999 G куплен'},'Купить дорогой паучий пончик или сидр в Хотленде.'),
404:('Сцена трёх переключателей завершена','В конце triswitchevent одновременно записываются 1 и plot=140. Это отметка завершения постановки, не позиции всех локальных переключателей.',{0:'Сцена ещё не завершена',1:'Сцена завершена'},'Пройти головоломку трёх переключателей с подсказками Альфис.'),
405:('Темы Катти и Братти: происхождение товаров','Последовательность пунктов разговора: 0 — о товарах, 1 — истоки товаров (новое), 2 — истоки мусора (новое), 3 — повторная тема. Не меняет наличие товаров на продажу.',{0:'О товарах',1:'Истоки товаров — новое',2:'Истоки мусора — новое',3:'Повторная тема'},'Выбирать эту тему в магазине Катти и Братти.'),
406:('Темы Катти и Братти: Меттатон','0 — первая тема о Меттатоне; 1 — новое продолжение о его происхождении; 2 — старое повторение. Не влияет на бой или рейтинг.',{0:'О Меттатоне',1:'Истоки Меттатона — новое',2:'Повторный разговор'},'Повторно выбирать разговор о Меттатоне у Катти и Братти.'),
407:('Темы Катти и Братти: Альфис и Азгор','0 — об Альфис; 1 — королевский учёный; 2 — об Азгоре; 3 — повторение последней темы. Это курсор знакомства с историей, а не состояние самих персонажей.',{0:'Альфис',1:'Королевский учёный',2:'Азгор',3:'Повторная тема'},'Последовательно обсуждать Альфис у Катти и Братти.'),
408:('Очередь первых боёв Хотленда','0/1/2 принуждают группы 51/50/52, последующие проверки продолжают очередь. Триггеры fire5, fire7, walkandbranch и walkandbranch2 исчезают, когда соответствующий порог уже пройден. Каждая такая встреча увеличивает счётчик.',{0:'Первая группа 51',1:'Группа 50',2:'Группа 52',4:'Четыре стартовых триггера исчерпаны'},'Проходить первые встречи Хотленда; это не счётчик убийств.'),
409:('Запрос/уведомление в комнате фартука обработано','Первый триггер в room_fire_apron пишет 1 и выбирает сообщение msc=754. При 1 повторное уведомление блокируется; текст отклонения также записывает 1. Не наличие фартука.',{0:'Уведомление ещё не обработано',1:'Больше не уведомлять'},'Пройти комнату фартука и обработать уведомление телефона.'),
413:('Ужин с Сансом в ресторане MTT','0 — приглашение ещё доступно; согласие ставит 1 и разрешает obj_sansdate3; окончание разговора пишет 2. Санс в другой комнате также скрывается при >0.',{0:'Приглашение не принято',1:'Ужин должен проиграться',2:'Ужин завершён'},'Принять приглашение Санса у ресторана и досмотреть беседу.'),
414:('Попытка воспользоваться неисправным лифтом Ядра','Первое обращение к лифту записывает 1. Альфис затем выбирает реплики с учётом того, пробовали ли лифт и слышали ли следующий звонок (415). Сам лифт не чинится этим флагом.',{0:'Лифт ещё не проверяли',1:'Лифт уже проверен'},'Подойти к лифту у начала Ядра.'),
415:('Вводный звонок в core2 состоялся','При пересечении первого триггера в core2 пишет 1; повторный объект звонка удаляется. Реплики зависят от проверки лифта 414. Поздний сюжет тоже может убрать звонок.',{0:'Первый звонок впереди',1:'Звонок обработан'},'Пройти первую комнату Ядра после лифта.'),
416:('Альфис уже дала указание на развилке Ядра','Записывается одним из двух звонков на пути в core5; один также ставит plot=185. Определяет её реакцию после следующего боя. Не выбирает сам путь и не обезвреживает лазеры.',{0:'Указание ещё не записано',1:'Указание уже дано'},'Пройти развилку и дождаться звонка Альфис.'),
417:('Вторая постановочная встреча Ядра завершена','Финал core_enemyevent2 ставит 1; при повторном входе событие удаляется. Силовой лазер выбирает иной звонок, если бой был пропущен. Убийственная ветка выставляет 1 заранее.',{0:'Событие может сработать',1:'Не повторять событие'},'Завершить вторую постановочную встречу в Ядре либо пройти предусмотренный маршрутный пропуск.'),
418:('Путь мудреца в Ядре открыт','Победа в shootguy_5 пишет 1. Вместе с альтернативами 419 или 420 открывает финальное силовое поле и позволяет лифту работать. Повторная головоломка создаётся решённой.',{0:'Путь мудреца не пройден',1:'Путь мудреца пройден'},'Решить стрелковую головоломку на пути мудреца.'),
419:('Путь воина в Ядре открыт','Нажатие переключателя core_warrior ставит 1 и делает scr_tempsave; повторная череда боёв удаляется. Это одна из трёх альтернатив открытия поля: 418/419/420, а не требование иметь все три.',{0:'Переключатель пути воина не нажат',1:'Путь воина пройден'},'Пройти цепочку боёв и нажать переключатель за ними.'),
420:('Силовое поле Ядра открылось от ожидания','Если поле закрыто, его таймер превышает 1800 шагов и нет диалога, ставится 1. Это обход путей мудреца/воина ожиданием, а не ошибка отсутствующих 418/419.',{0:'Ожиданием не открывали',1:'Поле открылось после ожидания'},'Оставаться у закрытого поля более 1800 игровых шагов (около минуты при 30 FPS).'),
421:('Позиция цепочки боёв пути воина','При X>220 первая встреча пишет 1; при X>360 следующая пишет 2. Счётчик предотвращает повторные запуски при движении назад. Награды и открытие переключателя не выдаются одной записью.',{0:'Первая встреча впереди',1:'Первый триггер пройден',2:'Второй триггер пройден'},'Идти по пути воина в Ядре.'),
423:('Очередь фиксированных встреч Ядра','Для 0/1/2 триггер выбирает группы 64/65/68; после открытия пути воина особая группа может заменяться. Продвижение также убирает ранее пройденные триггеры. Не число побеждённых врагов.',{0:'Группа 64',1:'Группа 65',2:'Группа 68'},'Проходить фиксированные столкновения в нижних комнатах и на мосту Ядра.'),
424:('Действие «Обратить» перед Меттатоном EX','0 — обычное действие «Отжарить». После подсказки спина доступна при 1; выбор меняет значение на 2 и запускает сцену с зеркалом. Одно значение 2 не создаёт Меттатона EX.',{0:'Поворот ещё недоступен',1:'Можно обратить Меттатона',2:'Действие выбрано'},'Дождаться подсказки в третьем бою Меттатона и выбрать новое ACT.'),
426:('Очередь случайных боёв Ядра','Первые значения 0–4 задают группы 62,64,65,66,68. После каждого выбранного боя +1; дальше остаётся обычная случайность. Совместно с 423 определяет сокращённое ожидание ранних боёв.',{0:'Группа 62',1:'Группа 64',2:'Группа 65',3:'Группа 66',4:'Группа 68',5:'Вступительная очередь пройдена'},'Проходить случайные встречи Ядра.'),
430:('Набор портретов Альфис','0 — обычный массив эмоций; 1 использует смещение +10, 2 — +15; 3 отдельно заменяет эмоции 0/7; 4 выбирает кадр spr_alphysface_new. Эпилог дополнительно заменяет некоторые эмоции. Не уровень дружбы.',{0:'Обычные лица',1:'Набор со смещением 10',2:'Набор со смещением 15',3:'Особые эмоции 0 и 7',4:'Новый покадровый портрет'},'Меняется в сценах сопровождения, свидания и лаборатории; друзья в эпилоге обнуляют.'),
431:('Выбранный этаж последнего лифта','0 — выход в финал Ядра, 1 — выход у замка. Двери задают исходную сторону, панель переключает 0/1. Это направление ближайшего выхода, не прохождение этажа.',{0:'Ядро',1:'Замок'},'Использовать панель лифта между Ядром и Новым Домом.'),
432:('Длинная первая поездка в последнем лифте уже была','При 0 играет elevator_last и длинный Alarm 560; при 1 — обычная elevator и сокращённая поездка. Финал поездки записывает 1.',{0:'Первая длинная поездка',1:'Повторная короткая поездка'},'Один раз проехать на последнем лифте.'),
433:('Соседний дом призрака открыт загадочным ключом','Использование предмета 60 у нужной двери удаляет ключ, ставит 1 и открывает дом. При повторном входе блокирующие дверь объекты не создаются.',{0:'Дом заперт',1:'Дом открыт'},'Купить загадочный ключ у Катти и Братти и использовать у соседнего с Напстаблуком дома.'),
434:('Ответ Хитс Флеймсману о его имени','0 — вопрос ещё не отвечен; 1 — сказали, что помнят имя; 2 — не помнят. Оба ненулевых состояния дают удивлённый спрайт, но разные повторные реплики.',{0:'Ещё не ответили',1:'Помню имя',2:'Не помню имя'},'Встретить Хитс Флеймсмана повторно и ответить.'),
435:('Бургерджинс перешёл от обслуживания к разговору','0 — первый сценарий перед темами разговора; первая покупка может поставить 1; после следующего вводного разговора 2 открывает обычные темы. На убийственном маршруте магазин поднимает значение до 2.',{0:'Начальное обслуживание',1:'После первой покупки',2:'Обычные разговоры открыты'},'Купить что-нибудь и поговорить с Бургерджинсом.'),
436:('Жалобы Бургерджинса на Меттатона','0 — тема «Меттатон», 1 — почему он плох, 2 — новое продолжение, 3 — повторение. Не меняет самого Меттатона.',{0:'Меттатон',1:'Почему Меттатон плох',2:'Почему ещё плох — новое',3:'Повторить последнюю тему'},'Последовательно выбирать тему Меттатона в MTT-магазине.'),
437:('История Бургерджинса, Катти и Братти','Общий курсор разговора между двумя магазинами. 0 — романтический совет, 1 — новая история гламбургера, 2 — Катти/Братти могут обсудить Бургерджинса, 4 — прояснение истории, 5 — новая тема о подругах, 6 — повтор, 7 — пикник, 8 — новое приглашение Катти, 9 — повтор приглашения.',{0:'Романтический совет',1:'История гламбургера',2:'Обсудить с Катти/Братти',4:'Прояснить историю',5:'Катти и Братти — новое',6:'Повторная тема',7:'Пикник',8:'Приглашение Катти — новое',9:'Повтор приглашения'},'Чередовать разговоры с Бургерджинсом и Катти/Братти; это связанная цепочка.'),
440:('Сколько стаканов взяли из кулера','При взятии воды +1. Нарисованная высота воды равна 21−счётчик, при <=0 вода не рисуется. Это не булев признак стакана в руках (за него отвечает 366).',{0:'Полный нарисованный кулер',21:'Вода больше не рисуется'},'Повторно брать стаканы у кулера.'),
441:('Сколько стаканов вылили при лежащей Андайн','Выбор выбросить воду увеличивает этот счётчик только пока существует obj_undynefall. Одновременно увеличивается общий счётчик 353. Это не отметка помощи Андайн.',{0:'При Андайн воду не выбрасывали',1:'Один стакан вылит'},'Взять воду и выбросить её, пока Андайн лежит рядом.'),
442:('У Катти и Братти куплено оружие','При покупке второго товара ставится 1, он становится sold out. 0 снова разрешает покупку; не удаляет ранее купленное оружие и не возвращает G.',{0:'Оружие ещё продаётся',1:'Оружие распродано'},'Купить пустой пистолет у Катти и Братти.'),
443:('У Катти и Братти куплена броня','При покупке третьего товара пишется 1 и выключается повторная продажа. Это отдельная отметка от экипированного ID и содержимого инвентаря.',{0:'Броня ещё продаётся',1:'Броня распродана'},'Купить ковбойскую шляпу у Катти и Братти.'),
444:('У Катти и Братти куплен загадочный ключ','После покупки последнего товара 1 означает sold out. Использование ключа и открытие дома хранятся отдельно в 433.',{0:'Ключ в продаже',1:'Ключ уже куплен'},'Купить загадочный ключ; его потеря не восстанавливает товар автоматически.'),
445:('Стейк в форме лица MTT уже куплен','Ограниченный четвёртый товар магазина Бургерджинса после покупки получает sold out. 0 разрешает покупку за 500 G, 1 запрещает. Не предмет в инвентаре.',{0:'Стейк продаётся',1:'Стейк распродан'},'Купить стейк за 500 G в MTT-магазине.'),
450:('Курсор рассказа монстров в Новом Доме','Фиксирует достигнутый порог рассказа; каждый story_engager запускается лишь если курсор ниже его threshold. 1/2 формируются также из двух ранних встреч 455/456. При 17 рассказ исчерпан; музыка и поздняя пацифистская ветка проверяются отдельно.',{0:'Рассказ не начат',1:'Первый ранний рассказ',2:'Оба ранних рассказа',17:'Рассказ завершён'},'Проходить коридоры Нового Дома и слушать историю. Не заменяет глобальный plot.'),
452:('Первый ключ от цепи Нового Дома','1 убирает ключ из комнаты asghouse2; совместно с 453=1 позволяет снять цепь и поставить 454=1. Предметного слота ключ не занимает.',{0:'Ключ ещё лежит',1:'Ключ на связке'},'Поднять первый ключ в доме Азгора.'),
453:('Второй ключ от цепи Нового Дома','1 убирает ключ из asghouse3. Нужен вместе с 452 для обычного открытия цепи. Сам по себе цепь не снимает.',{0:'Ключ ещё лежит',1:'Ключ на связке'},'Поднять второй ключ в доме Азгора.'),
454:('Цепь в доме Азгора','0 — не осмотрена; первое взаимодействие пишет 0.5; два ключа дают 1 и снимают преграду. Лабораторный финал тоже ставит 1 напрямую — поэтому 1 без обоих ключей не всегда ошибка.',{0:'Цепь не осматривали',0.5:'Осмотрена, нужны ключи',1:'Проход открыт'},'Собрать 452/453 и взаимодействовать с цепью, либо пройти предусмотренный поздний пацифистский переход.'),
455:('Левый ранний рассказ в Новом Доме','При первом пересечении X<90 в asghouse2 ставит 1 и запускает рассказ. Совместно с 456 пересчитывает раннюю фазу 450. Не убийство рассказчика.',{0:'Не запускался',1:'Триггер пройден'},'Пройти соответствующий край комнаты в Новом Доме.'),
456:('Правый ранний рассказ в Новом Доме','При X>460 в asghouse3 ставит 1 и запускает рассказ. Его сумма с 455 определяет 450=1 или 2; соседние триггеры проверяют также <2.',{0:'Не запускался',1:'Триггер пройден'},'Пройти правую часть комнаты с ранним рассказом.'),
457:('Отложили бой с Азгором у барьера','Ответ о неготовности пишет 1 и переводит сцену в ожидание. При повторном подходе используется другой короткий разговор. Не победа и не пропуск боя.',{0:'Первое предложение боя',1:'Уже просили подождать'},'Сказать Азгору, что сначала хочется закончить другие дела.'),
458:('Полежали на полу с Напстаблуком','После прекращения совместного лежания ставится 1. Хозяин затем говорит, что продолжит работать над CD-миксом. Визит и музыка имеют отдельные флаги.',{0:'Совместный отдых ещё не отмечен',1:'Полежали вместе'},'Принять предложение Напстаблука полежать и затем встать.'),
459:('Пункт назначения лодочника','1 направляет лодку в Сноудин, 2 — Водопадье, 3 — Хотленд. Диалог переводит локальный первый/второй ответ в эти абсолютные пункты. Не наличие доступа к лодке.',{0:'Направление не выбрано',1:'Причал Сноудина',2:'Причал Водопадья',3:'Причал Хотленда'},'Согласиться на поездку и выбрать место.'),
460:('Число завершённых поездок лодочника','По завершении поездки +1. После первой сокращается приглашение, чётность при входе выбирает обычную/собачью лодку через 461; при ==1 реплика поездки принудительно имеет индекс 17.',{0:'Поездок не было',1:'Первая завершена'},'Пользоваться лодкой после открытия маршрута (plot>=122).'),
461:('Текущий облик лодки','При соответствующем входе вычисляется из чётности 460: нечётный счётчик даёт 1 (собачья лодка), чётный — 0 (обычная). Ручная запись может быть сразу пересчитана.',{0:'Обычная лодка',1:'Собачья лодка'},'Чередовать завершённые поездки и возвращаться к лодочнику.'),
462:('Повторный телефонный разговор в этой комнате','scr_papcall выбирает повторную реплику при >0. Создание главного героя, некоторые звонки Альфис и сцены обнуляют. Это локальный курсор повтора, не общий счётчик всех звонков.',{0:'Первый разговор в комнате',1:'Повторный разговор'},'Позвонить Папирусу несколько раз без выхода из комнаты.'),
465:('Андайн участвует в звонках Папирусу','После дружеского визита ставится 1 вместе с 389=4. Телефонный пункт 210 переименовывается в «Папирус и Андайн»; scr_papcall добавляет её реплики только при ==1.',{0:'Отвечает только Папирус',1:'Совместные звонки'},'Завершить дружеский визит к Андайн и разговор во дворе.'),
470:('Особый повтор звонка про комнату с водой','Первый соответствующий совместный звонок ставит 1. При повторе Андайн отвечает коротким возмущённым вопросом о комнате вместо полной беседы про зонт.',{0:'Полный первый разговор',1:'Короткий повтор'},'Позвонить Папирусу и Андайн в комнате этой ветки scr_papcall.'),
475:('Послефинальное появление Флауи подавлено','Ставится после убийства увядающего Флауи; финальный сценарий также может выставить 1 по памяти INI. При 0 mainend создаёт obj_endflowey; при 1 его подсказка не появляется. Смена одного флага не отменяет память Flowey/K.',{0:'Послефинальный Флауи разрешён',1:'Появление подавлено'},'Выбрать убийство Флауи в конце нейтральной ветки; состояние связано с INI.'),
476:('Последний удар Азгору нанёс игрок','Выбор удара в финальной сцене ставит 1. endflowey тогда учитывает дополнительное убийство и меняет обвинения/совет. 0 соответствует ветке, где этого удара не было; не воскрешает Азгора.',{0:'Игрок не наносил финальный удар',1:'Азгор добит игроком'},'Выбрать FIGHT после завершения боя с Азгором.'),
357:('Порядок первых встреч в начале Водопадья','При 0, 1, 2 назначаются группы боя 40, 43, 53 соответственно; после выбора счётчик растёт. Поздние значения оставляют обычный случайный выбор. При первом входе в water5 сокращается ожидание первой встречи.',{0:'Группа 40',1:'Группа 43',2:'Группа 53',3:'Вводная последовательность закончена'},'Проходить случайные встречи в начальной части Водопадья.'),
358:('Порядок встреч во второй части Водопадья','Значения 0–3 принуждают группы 41, 42, 54, 55, затем счётчик увеличивается. После 3 работают обычные случайные варианты и отдельная проверка исчерпания популяции.',{0:'Группа 41',1:'Группа 42',2:'Группа 54',3:'Группа 55',4:'Обычный выбор'},'Запускать встречи, управляемые encounterer_water2.'),
360:('Два звуковых потока дождя созданы','1 означает активный obj_ambientrain с потоками rain и rain_deep. При уходе громкости затухают, потоки освобождаются и флаг обнуляется. scr_load всегда сбрасывает его, поэтому переносить 1 как сюжетный прогресс нельзя.',{0:'Потоки не активны',1:'Дождь воспроизводится'},'Войти в дождливые комнаты Водопадья. Для файловой правки — 0.'),
361:('Текущая громкость обычного дождя','Дробная громкость rain.ogg: старт 0.5, у статуи 0; меняется по 0.02 при переходах. scr_load сбрасывает в 0. Не количество дождей или пройденный этап.',{0:'Тишина',0.5:'Обычная стартовая громкость'},'Смешивается автоматически при движении между дождливыми комнатами; не переносить как постоянную настройку.'),
362:('Текущая громкость глубокого дождя','Громкость rain_deep.ogg: в обычной комнате начинает с 0, у статуи/перед Андайн — с 0.5, затухает по 0.02. Загрузчик обнуляет.',{0:'Тишина',0.5:'Глубокий дождь'},'Задаётся obj_ambientrain, это временная звуковая переменная.'),
363:('Дескриптор потока rain.ogg','Результат caster_load, который передают caster_set_volume и caster_free. Это динамический номер ресурса текущего процесса, НЕ ID музыки из каталога. При освобождении −1, при загрузке сейва 0; произвольное положительное число может обратиться к чужому потоку.',{0:'Сброс загрузчиком',-1:'Поток освобождён'},'Создаётся при входе под дождь; вручную не подбирать положительные ID.'),
364:('Дескриптор потока rain_deep.ogg','Аналог 363 для глубокого слоя дождя. Динамический handle действителен только в текущем процессе; после освобождения −1, после scr_load 0. Не выбирает песню по номеру.',{0:'Сброс загрузчиком',-1:'Поток освобождён'},'Управляется obj_ambientrain. В сейве нормализуется в 0 при загрузке.'),
366:('Герой несёт стакан воды','Кулер ставит 1 и меняет спрайты героя на вариант с водой. Выливание, помощь упавшей Андайн или автоматическая потеря воды снимают флаг и возвращают спрайты. Одной записи 1 в памяти мало для правильной анимации.',{0:'Воды нет',1:'Стакан в руках'},'Взять стакан у кулера перед упавшей Андайн; для её спасения нужно взаимодействие, не только наличие воды.'),
368:('Подавление уведомлений Альфис','При 1 obj_notify_room выставляет donotcall. Убийственная ветка лаборатории ставит этот флаг вместе с 367,369 и решёнными головоломками. Не меняет историю отношений сам по себе.',{0:'Уведомления разрешены',1:'Уведомления подавлены'},'Выставляется сюжетным пропуском лаборатории на соответствующем маршруте.'),
369:('Курсор прочитанных статусов Альфис','Хранит последний порог последовательности уведомлений. В позднем Хотленде записываются 24/25, следующий звонок — 26. Убийственная ветка пишет 99, чтобы пропустить всю последовательность. Меньшее значение разрешает повторные сообщения, но только в их комнатах.',{0:'Начало последовательности',24:'Поздний статус о человеке',25:'Следующий поздний статус',26:'Поздний звонок обработан',99:'Все уведомления подавлены маршрутом'},'Читать статусы по пути через Хотленд. Это порядковый курсор, а не точное число реально увиденных сообщений.'),
370:('Тип короткой атаки в мире','Быстрый генератор смотрит: 1 — копья Андайн, 2 — лазеры Хотленда, 3 — усиленные лазеры Ядра. Сценарии одновременно готовят рамку, таймер и объекты; флаг отдельно их не создаёт.',{0:'Тип не выбран',1:'Копья',2:'Лазеры Хотленда',3:'Лазеры Ядра'},'Попасть в соответствующую сюжетную атаку.'),
371:('Первый лазерный переключатель','В room_fire_lasers1 значение 1 восстанавливает отключённое состояние через Alarm; переключение включения/выключения пишет 1/0. Убийственная ветка лаборатории заранее пишет 1.',{0:'Лазеры включены',1:'Выключатель сработал'},'Нажать переключатель первой лазерной комнаты.'),
372:('Альфис отключила лазеры при 1 HP','Пока 0, соответствующий лазер не даёт умереть: HP=0 превращается в 1. При 1 HP и свободном управлении Альфис звонит, отключает лазеры и записывает 1; последующие звонки учитывают её вмешательство.',{0:'Помощь ещё не срабатывала',1:'Альфис уже помогла'},'Потерять HP на первых лазерах при доступных звонках Альфис; сцена имеет ограничения plot и flag[367].'),
373:('Звонок и отключение лазера в fire8','Первое пересечение триггера пишет 1. При повторном создании комнаты 1 отключает obj_bluelaser_o и удаляет повторный звонок. Диалог учитывает прежнюю помощь 372.',{0:'Звонок ещё доступен',1:'Звонок обработан и лазер отключается'},'Пройти room_fire8 по обычному маршруту.'),
374:('Открытие прохода fire8 через стрелковую загадку','Сохраняет переключатель комнаты fire8: 1 восстанавливает открытый проход. Победа в shootguy_2 и убийственный пропуск ставят 1; выключение переключателя может вернуть 0.',{0:'Проход не открыт',1:'Проход открыт'},'Решить вторую соответствующую стрелковую головоломку.'),
375:('Открытие прохода fire9 через стрелковую загадку','Пара к 374 для комнаты fire9: победа в shootguy_1 пишет 1; комнатный переключатель сохраняет 0/1. Не требует менять plot вручную.',{0:'Проход не открыт',1:'Проход открыт'},'Решить первую соответствующую стрелковую головоломку.'),
376:('Координата перехода между конвейерами','Не boolean: сохраняет X героя перед переходом. При >0 следующий conveyorsnapper ставит X=значение−200, Y=−20, включает анимацию приземления и сразу обнуляет флаг. Большое произвольное число телепортирует за пределы комнаты.',{0:'Переход не ожидается'},'Устанавливается переходом с конвейера; вне него держать 0.'),
377:('Особый исход полёта с джетпаком','Ставится в ветке con=33 после заключительной сцены полёта, меняет следующий звонок Альфис в кулинарном шоу. Это отметка сценарного исхода, не наличие джетпака; транспорт и таймер создаются отдельно.',{0:'Обычный последующий звонок',1:'Альтернативный звонок после сцены'},'Завершить соответствующую ветку полёта в кулинарном шоу.'),
378:('Золото, потраченное на хот-доги Санса','При успешной покупке прибавляется 30 одновременно со списанием 30 G. Это накопленная сумма, не текущий баланс и не число хот-догов на голове.',{0:'Покупок нет',30:'Одна покупка',60:'Две покупки'},'Покупать хот-доги при свободном слоте инвентаря.'),
379:('Очередь реплик и Хот-Кота у Санса','Счётчик покупок. Только при ==1 следующая покупка выдаёт Хот-Кот (39), остальные — Хот-Дог (38). После успеха увеличивается; значения 0–4 выбирают отдельные шутки.',{0:'Первая покупка: Хот-Дог',1:'Следующая покупка: Хот-Кот',2:'Снова Хот-Дог',3:'Следующая шутка',4:'Последняя особая шутка'},'Покупать еду у Санса. Смена не выдаёт предмет.'),
380:('Сколько хот-догов предложено на голову','Первый переполненный инвентарь запускает шутку и счётчик. При >0 и занятом последнем слоте добавляются объекты хот-догов, максимум 30 одновременно. Счётчик сам не восстанавливает стопку объектов после загрузки.',{0:'Шутка ещё не началась',1:'Первый голово-дог уже предложен'},'Попросить еду у Санса с полным инвентарём.'),
381:('Объяснение лимита 30 голово-догов','При первом превышении объектного лимита даётся длинное объяснение и ставится 1. Повторные попытки получают короткий отказ. Не сам размер стопки.',{0:'Лимит ещё не объясняли',1:'Длинное объяснение уже было'},'Набрать 30 хот-догов на голову и попросить ещё.'),
382:('Текущая цена подкупа Маффет','На старте боя 10 G. Вырывание может снизить цену вдвое с округлением вверх (не ниже 1); платежи повышают следующую цену. Победа использует это число и для награды. Не общий долг.',{1:'Минимальная цена',10:'Стартовая цена'},'Использовать действия «Вырываться» и «Заплатить» в бою Маффет; цена динамическая.'),
383:('Суммарно заплачено Маффет в бою','Успешный подкуп списывает текущую цену 382 из золота и прибавляет её сюда. Специальная награда вычисляется как 2×flag[59]+2×383, максимум 999. Ручная запись не списывает золото.',{0:'В этом счётчике платежей нет'},'Выбирать «Заплатить» с достаточным количеством G.'),
385:('Жёлтая кнопка телефона в бою Меттатона','0 — действие «Визжать», 1 — кнопка стала доступна после сюжетной подсказки, 2 — нажата, запущена трансформация сцены. 1 также меняет рамку атак при HP>1.',{0:'Кнопка ещё недоступна',1:'Можно нажать жёлтую кнопку',2:'Кнопка уже нажата'},'Дождаться подсказки Альфис и выбрать действие с кнопкой.'),
386:('Начальное восстановление мостовых цветов','bellblossom и входы водной головоломки выставляют 1; при создании water_bridgepuzz1 с 1 игра раскладывает предусмотренный набор цветов. Это локальное состояние раскладки, не решённость всех цветочных загадок.',{0:'Начальная раскладка ещё не отмечена',1:'Раскладка восстанавливается'},'Пройти соответствующий вход/сброс цветов в Водопадье.'),
387:('Первая красная награда игры в шар','При первом красном результате чтение флага даёт 50 G и пишет 1. Повторный красный результат показывает описание решительности без этой первой награды.',{0:'Награда 50 G ещё доступна',1:'Первая красная награда получена'},'Быстро загнать снежный шар в лунку и прочитать красный флажок.'),
388:('Ожидается анимация падения в новую комнату','Яма/переход ставит 1. falltransition или dogtransition при создании читает 1, меняет позицию/прозрачность/скорость героя и сбрасывает в 0. Не постоянная открытая дверь.',{0:'Обычный вход',1:'Вход с падением'},'Использовать яму или соответствующий собачий переход. Не оставлять 1 для произвольной комнаты.'),
389:('Прогресс дружеского визита к Андайн','3 записывается после дружеского боя при переходе во двор; затем сцена после визита ставит 4 и flag[465]=1. Триггер встречи Напстаблука превращает 4 в 5. Условия письма проверяют >=3, но также убийства и другие этапы.',{0:'Визит не завершён',3:'Дружеский бой завершён, предстоит разговор во дворе',4:'Разговор после визита пройден',5:'Последующее состояние после перехода'},'Подружиться с Папирусом, напоить Андайн, пройти визит к ней без убийств.'),
390:('Дополнительный вариант лица Андайн','При 1 эмоция 9 заменяется спрайтом undyne9_2; при 2 эмоции 1 и 9 получают варианты _3. Сценарий дружбы переключает 0→1→2→0; друзья в эпилоге сбрасывают 0. Это не уровень отношений.',{0:'Обычный портрет',1:'Первый особый портрет эмоции 9',2:'Второй вариант эмоций 1/9'},'Появляется во время сцен приготовления/дружбы с Андайн.'),
391:('Еда, заказанная с Сансом у Гриллби','Выбор 1 показывает картошку фри, 2 — бургеры; объект свидания выбирает соответствующий спрайт еды. Предмет в инвентарь не добавляется.',{0:'Заказ ещё не выбран',1:'Картошка фри',2:'Бургеры'},'Принять приглашение Санса и выбрать заказ.'),
393:('Звуковой handle атаки сферы Маджика','Временный дескриптор: при !=0 завершение/столкновение сферы освобождает поток и обнуляет поле, затем возобновляет звук. Не ID предмета или сюжетный результат.',{0:'Дополнительный поток не назначен'},'Обслуживается wizardorb_chaser. Нельзя безопасно выбирать произвольное положительное значение.'),
395:('Сколько из шести бомб шоу обезврежено','После каждой законченной мини-сцены прибавляется 1. Тикер показывает 6−значение; 1/5/6 включают отдельные реплики/завершение. Простая запись 6 не удалит шесть объектов и не проиграет финал.',{0:'Шесть бомб впереди',1:'Одна обезврежена',5:'Осталась одна',6:'Все шесть обработаны'},'Обезвреживать предметы в новостном шоу Меттатона.'),
396:('Позиция вступления Маффет в паутине','По мере продвижения +1 и триггер сдвигается на 90 пикселей. При 5/6 усиливается ограничение ходьбы. Если tempvalue[11]>0, создание поднимает малые значения до 5. После plot>164 вступление убирается.',{0:'Начало паучьего коридора',5:'Поздняя фаза замедления',6:'Финальная фаза вступления'},'Продвигаться через паутину перед боем с Маффет.'),
193:('Разговоры Андайн после финала','Счётчик разговоров у друзей: 0 — первое обращение, 1 — просьба к Альфис посмотреть битвы и принцесс, >=2 — просьба передать привет Напстаблуку. Последняя ветка также ставит flag[194]=1. Каждый разговор прибавляет 1.',{0:'Первый разговор',1:'Альфис, битвы и принцессы',2:'Передай привет Напстаблуку'},'Повторно обращаться к Андайн в эпилоге.'),
195:('Разговоры Папируса после финала','0 — просит Азгора о Королевской страже; 1 — обещает Фриск дружбу; 2 — разговор о прогулке и полёте; >=3 — повторный ответ. На каждое обращение +1; не меняет прежнюю дружбу или исход боя.',{0:'Королевская стража',1:'Дружба с Фриск',2:'Прогулка',3:'Повторный ответ'},'Разговаривать с Папирусом у друзей после Азриэля.'),
196:('Разговоры Альфис после финала','0 выбирает первый диалог, 1 — фанфики о реальных людях, 2 — человеческий интернет и совместный просмотр с Андайн; >=3 — повторная реплика. Увеличивается каждым разговором, не заменяет свидание.',{0:'Первый диалог',1:'Фанфики',2:'Интернет и Андайн',3:'Повторная реплика'},'Повторно говорить с Альфис в эпилоге.'),
197:('Разговоры Азгора после финала','0 — извинение за попытку забрать душу; 1 — отдельная следующая беседа; >=2 — совет гулять в погожие дни. Каждый разговор увеличивает счётчик.',{0:'Извинение',1:'Вторая беседа',2:'Совет прогуляться'},'Повторно говорить с Азгором в эпилоге.'),
225:('В Ядре показано отсутствие врагов','Контроллер встреч Ядра записывает 1 при переходе к состоянию alldead=2. Это отметка исчерпанной популяции, не сама квота: оставшихся врагов считают другие поля, прежде всего 205.',{0:'Отметки нет',1:'Пустая популяция отмечена'},'Исчерпать популяцию на соответствующем маршруте и запустить следующую встречу в Ядре.'),
250:('Разговор с продавцом Доброженого у отеля','Завершение вступления у отеля пишет 1. 0 показывает первое предложение за 12 G; >=1 — короткое повторное. В эпилоге первый ответ сообщает, что два парня выкупили всё, последующий — радость от успеха.',{0:'Первое вступление',1:'Повторное предложение/ответ'},'Поговорить с продавцом у входа в отель. Не выдаёт мороженое.'),
256:('Пять золотых из кассы Катти и Братти','При первом успешном ограблении пустой кассы магазин добавляет 5 G и ставит 1. Повторное получение блокируется. Ручная установка 1 не прибавляет денег.',{0:'Деньги ещё в кассе',1:'Касса ограблена'},'Забрать деньги, когда Катти и Братти отсутствуют.'),
260:('Хотя бы раз использовали лечебный предмет','scr_recoitem записывает 1 при восстановлении предметом. При 0 Санс в нейтральной концовке может отметить прохождение без еды; при LV=1 и стартовой броне выбирает дополнительную реплику о вызове.',{0:'Восстановление предметом не отмечено',1:'Лечебный предмет использован'},'Съесть еду/использовать предмет, вызывающий scr_recoitem. Смена не лечит героя.'),
261:('Собака-оболочка рассыпалась в остатки','Первое взаимодействие с поддельной собакой показывает распад и ставит 1. При следующем входе сразу рисуется кучка пуха.',{0:'Собачья оболочка цела',1:'Осталась кучка'},'Попытаться погладить собаку-оболочку в ледяной комнате.'),
262:('Заказ Морского Чая в отеле выполнен','После передачи предмета 41 под дверь игра удаляет чай, добавляет 99 G и пишет 1. Повторная выдача награды блокируется.',{0:'Заказ не выполнен',1:'Чай доставлен, награда выдана'},'Иметь Морской Чай, постучать в дверь клиента и согласиться передать его. Флаг отдельно не обменивает предмет/золото.'),
263:('Заказ Коричного Кролика в отеле выполнен','Передача предмета 21 под дверь даёт 99 G и значение 1. Предмет удаляется самим сценарием, не записью флага.',{0:'Заказ не выполнен',1:'Кролик доставлен, награда выдана'},'Принести Коричного Кролика клиенту за дверью отеля.'),
264:('Хот-Дог обменян на Тихого Щенка','При наличии предмета 38 и флаге 0 сцена убирает Хот-Дог, выдаёт предмет 62 и ставит 1. Ветка Хот-Кота отдельная и этой награды не даёт.',{0:'Обмен ещё доступен',1:'Тихий Щенок уже получен'},'Положить Хот-Дог перед нужной дверью отеля. Запись 0 не возвращает уже отданный предмет.'),
265:('Пауза между торгами Темми','При <=1 продажа запускает особый торг и ставит 9. Обычная завершённая продажа не-хлопьев уменьшает число на 1. Не таймер в секундах и не цена предмета.',{0:'Особый торг доступен',1:'Особый торг доступен',9:'Торг только что запущен'},'Продавать предметы Темми. Хлопья отдельно контролируются flag[266].'),
266:('Особый торг за хлопья Темми уже был','Первая попытка продать предмет 22 при 0 принудительно открывает особый торг, даже если обычный cooldown[265] ещё велик, и ставит 1.',{0:'Особый торг за хлопья ещё доступен',1:'Первый торг уже использован'},'Предложить Темми её хлопья. Не означает, что они сейчас есть в инвентаре.'),
267:('Оплата номера в MTT Resort','После оплаты 200 G пишет 1. Следующий разговор объясняет, что выход требует повторной оплаты, и меняет 1 на 2. 2 показывает короткое предложение за 200 G. Постоянного бесплатного ключа нет.',{0:'Первое предложение',1:'Последний номер оплачен',2:'Правило повторной оплаты объяснено'},'Оплатить номер и поговорить с портье после выхода.'),
269:('Гриб оказался Темми','После окончания превращения obj_hivestem пишет 1. Меняет его спрайт на говорящую Темми; и он, и соседний judgeshroom затем отвечают «пРИВК».', {0:'Превращение ещё не показано',1:'Темми раскрыта'},'Взаимодействовать с грибом в деревне Темми и досмотреть сцену.'),
270:('Грибная головоломка активирована','Зажечь не менее четырёх грибов — запись 1; посещение объекта judgeshroom также устанавливает 1. При повторном входе головоломка создаётся с solvent=1. Поздний plot тоже способен открыть путь независимо.',{0:'Не решена',1:'Открытие сохранено'},'Зажечь грибы и открыть путь в деревню Темми.'),
271:('Специальная шкала HP в бою с Сансом','Обычный контроллер боя сбрасывает 0. Санс включает 1; scr_binfowrite выбирает специальное отображение вместо обычных красной/жёлтой полосок. Сам флаг не создаёт карму и не начинает бой.',{0:'Обычный HUD боя',1:'HUD Санса'},'Устанавливается самим боем с Сансом; вне боя держать 0.'),
272:('Экран смерти после ложной пощады Санса','После ловушки пощады ставится 1. Экран смерти загружает dogsong вместо gameover, меняет воспроизведение и выбирает текст msgnum=300. Не включает бессмертие и не влияет на честную пощаду других врагов.',{0:'Обычная смерть',1:'Особая смерть в ловушке Санса'},'Пощадить Санса в предложенной им ловушке.'),
275:('Сломанная ветка и скрытое появление Санса','0 — ветка целая; при столкновении становится 1 и flag[47]=2. После ложного появления Санса записывается 2, повторный триггер удаляется. Сохраняет постановку леса между входами.',{0:'Ветка целая',1:'Ветка сломана',2:'Появление Санса отыграно'},'Пройти начальный лес после Руин.'),
276:('Колледж Темми оплачен','При 0 четвёртая покупка — колледж за 1000 G. После оплаты/сцены пишет 1: появляется выпускная шапка и продажа брони Темми, цена которой зависит от счётчика смертей. Установка 1 не списывает 1000 G.',{0:'Колледж ещё предлагается',1:'Колледж завершён; продаётся броня'},'Оплатить колледж в магазине Темми и дождаться возвращения.'),
278:('Цветные плитки пройдены','Успешный финал multitileevent пишет 1 и отключает огонь своим сценарием. Папирус по телефону после этого хвалит решение. Сам флаг не выполняет локальные переключатели головоломки.',{0:'Успех не отмечен',1:'Головоломка пройдена'},'Дойти до конца цветных плиток в Хотленде.'),
286:('Номер прочитанного SMS Ториэль в эпилоге','scr_torcall выбирает текст по текущему числу и увеличивает его, только если оно меньше доступного лимита flag[287]. При равенстве сообщает, что новых сообщений нет. Это не телефонный ID.',{0:'Первое сообщение об обучении печати',1:'Ториэль спрашивает о прогулке',2:'Исправление опечатки'},'Читать сообщения Ториэль после истинного финала; новые входы в комнаты расширяют лимит.'),
287:('Сколько SMS Ториэль сейчас доступно','После финала ставится 1. При создании героя в эпилоге, если лимит <= уже прочитанного flag[286], становится 286+1. Иначе чтение сообщения не продвигается. Это верхняя граница, не прочитанный номер.',{1:'Доступно первое сообщение'},'Переходить между комнатами в эпилоге. Обычно не должен быть меньше flag[286].'),
290:('Папирус начал бой в убийственной ветке','Создание босса при murder-условии записывает 1 и меняет сам бой. Позднее коробка костей использует это для реплики об атаках, которые он не применил. Запись не активирует весь маршрут.',{0:'Обычный вариант боя',1:'Начат особый вариант'},'Прийти к Папирусу с выполненными условиями убийственного маршрута.'),
291:('Электрический лабиринт пропущен','В альтернативной ветке постановки Папируса пишется 1. Его последующий телефонный ответ говорит, что загадку даже не решили, вместо воспоминания об ударе током.',{0:'Обычное воспоминание о лабиринте',1:'Воспоминание о пропуске'},'Пройти альтернативную ветку сцены электрического лабиринта.'),
292:('Xbox: тройка вишен в автомате','Три вишни ставят 1 и открывают декорацию и проверку dog_cherry. Ручная запись не начисляет выигрыш. Текущее PS4-святилище использует поля 159–162. В оставшемся старом обработчике коробки trashzone1 тоже есть обращения к 292, но это не прогресс текущего PS4-бонуса и не основание конвертировать его при смене режима.',{0:'Вишни ещё не выиграны',1:'Тройка вишен выиграна'},'Получить три вишни в Xbox-автомате.'),
293:('Xbox: выигрыш призраков','Тройка символа 3 ставит 1; автомат показывает соответствующую декорацию и проверяет dog_ghosts. Деньги начисляет исход вращения, не сам флаг.',{0:'Тройка ещё не отмечена',1:'Призраки выиграны'},'Выиграть три призрака в Xbox-автомате.'),
294:('Xbox: выигрыш костей','Тройка символа 4 даёт выигрыш 30 монет и записывает 1; открывает декорацию и dog_bones. Ручное значение монеты не прибавляет.',{0:'Не выиграно',1:'Кости выиграны'},'Выиграть три кости в Xbox-автомате.'),
295:('Xbox: выигрыш магических символов','Тройка символа 5 даёт 75 монет и пишет 1; открывает декорацию и dog_spell. Проверки ждут именно 1.',{0:'Не выиграно',1:'Магическая тройка выиграна'},'Получить соответствующую тройку в Xbox-автомате.'),
296:('Инструкция коробки PS4 прочитана','Первое согласие в объяснении пожертвований пишет 1. При 0 NPC открывает msc=952, при >=1 сразу форму пожертвования msc=960. Это не сумма.',{0:'Сначала объяснение',1:'Сразу пожертвование'},'Осмотреть коробку и принять объяснение.'),
297:('Xbox: развитие комнаты автомата и разговоров','0 запускает вступительную сцену, её конец пишет 1 и разрешает автомат. >=2 добавляет декорации; >=3 — поздние разговоры Санса. 3.1 — законное дробное значение: снежная реплика уже услышана. Не округлять до целого.',{0:'Вступление',1:'Автомат открыт',2:'Следующее состояние комнаты',3:'Поздние разговоры',3.1:'Реплика о снегопаде услышана'},'Посещать Xbox-комнату, выигрывать и разговаривать с Сансом. Это не сумма пожертвований.'),
298:('Xbox: доступные монеты автомата','Баланс: вращение −1, обмен 25 G даёт 5 монет с ограничением 2500; пожертвование переносит выбранную сумму в flag[299]. Большие балансы усиливают визуальные частицы, коэффициент ограничен 10.',{0:'Нет монет',5:'Хватает на пять вращений',2500:'Предел покупки монет'},'Менять золото на монеты или выигрывать. Естественные значения — целые 0–2500; начисление выигрыша может иметь отдельные ограничения.'),
299:('Xbox: суммарно пожертвованные монеты','Пожертвование уменьшает 298 и увеличивает 299; пороги открывают изменения комнаты. При >=500 интерфейс показывает МАКС. scr_saveprocess дублирует это число в хвостовую строку xbox_coins_donated, поэтому редактор должен менять их вместе.',{0:'Ничего не пожертвовано',10:'Первый порог',25:'Следующий порог',50:'Следующий порог',500:'Максимальное оформление'},'Пожертвовать монеты через коробку в Xbox-комнате.'),
10:('Результат пощады в текущем бою','scr_monsterdefeat при killed=0 и завершения встреч с амальгамами пишут 1. По этой отметке выбирается реакция Ториэль на учебный бой. Не общий счётчик пощад и не оживление врага.',{0:'Пощада не отмечена',1:'Мирное завершение отмечено'},'Пощадить противника; общий накопительный счётчик — flag[23].'),
13:('Противник покинул учебный бой','Обработчики ухода монстра Other_0 ставят 1 вместе с flag[14]=3, убирая противника из массива боя. SCR_TEXT проверяет это при ответе Ториэль. Установка не вызывает уход существующего врага.',{0:'Уход не отмечен',1:'Монстр ушёл'},'Довести учебную встречу до ухода противника.'),
14:('Код исхода встречи с манекеном','Destroy учебного манекена ставит 1; уход монстра из сцены — 3. Это запись исхода, а не номер сюжетной главы. Самостоятельная смена не завершает бой и не начисляет награды.',{0:'Исход не записан',1:'Учебный манекен уничтожен',3:'Противник покинул бой'},'Закончить учебную встречу естественным способом.'),
15:('Сохранение фоновой музыки при переходе в бой','При 0 obj_battler приглушает текущую музыку, а возврат героя создаёт её плавное восстановление. При 1 эта стандартная обработка пропускается: копья Андайн, лазеры и постановочные бои управляют звуком сами.',{0:'Обычный переход музыки',1:'Музыкой управляет сцена'},'Выставляется обработчиком конкретной встречи. Вне неё принудительное значение может оставить неверный звук.'),
16:('Особая траектория сердца при входе в бой','obj_transheart при 1 меняет начальную позицию и цель перелёта души. Используется быстрыми сценами копий/лазеров и сюжетными боями вместе с flag[15]. Не задаёт цвет души.',{0:'Обычный переход',1:'Переход внутри специальной сцены'},'Включается при столкновении с сюжетной атакой и снимается после неё.'),
17:('Блокировка открытия меню во время сцены','Меню героя разрешено при interact=0 и flag[17]=0. Погони Андайн, телешоу и лежание с Напстаблуком временно ставят 1; завершение снимает блокировку. Не сюжетная победа.',{0:'Меню разрешено при свободном управлении',1:'Сценарная блокировка меню'},'Автоматическая защита сцен; постоянная 1 в сейве может оставить меню недоступным.'),
20:('Кадр/поза говорящего персонажа','Текстовый движок записывает сюда цифровой управляющий символ реплики. Актёры Меттатона, Альфис и другие читают его как индекс позы. Значение 1 не имеет единого смысла для всех сцен; Меттатон проверяет 1–9, некоторые актёры — <7.',{0:'Базовая поза'},'Меняется управляющими кодами диалога. Для этого поля нельзя честно назначить общий список эмоций всех персонажей.'),
23:('Накопленное число мирных завершений','Увеличивается на 1 при scr_monsterdefeat(killed=0), завершениях амальгам и специальном мирном выходе Напстаблука. Это число обработанных мирных исходов, не число всех встреч и не доказательство отсутствия убийств.',{0:'Мирные исходы ещё не начислялись'},'Пощадить монстров или закончить соответствующие особые встречи. Значения — неотрицательные целые.'),
40:('Сколько раз поздоровались с Ториэль по телефону','При выборе приветствия счётчик растёт один раз за диалог. Для 1, 2, 3 написаны разные ответы; при >3 используется повторный ответ. Номер телефонного контакта хранится отдельно.',{0:'Ещё не здоровались',1:'Первый привет',2:'Второй привет',3:'Третий привет',4:'Повторяющийся ответ'},'Выбирать «Сказать привет» в телефоне, пока Ториэль отвечает.'),
47:('Появление силуэта Санса перед первым знакомством','Скрипты лесной постановки меняют флаг: триггер тёмного Санса пишет −1, сломанная ветка — 2, ложное появление — 3; таймер шагов затем увеличивает число. При >2 повторный триггер удаляется. Это фаза эффекта, не дружба с Сансом.',{-1:'Триггер силуэта запущен',0:'Начальный лес',2:'Ветка сломана',3:'Повторное появление уже запущено'},'Идти по лесу после выхода из Руин. Ставить промежуточную фазу вне комнаты бессмысленно.'),
56:('Что произошло с подаренным куском снеговика','0 — просьба ещё не принята. После подарка 1; если кусок исчез из инвентаря и ящиков, можно получить замену и значение 2. Поедание на глазах снеговика даёт 4, разговор после этого — 5. Установка не выдаёт предмет 16.',{0:'Подарка ещё нет',1:'Первый кусок выдан',2:'Замена уже выдана',4:'Кусок съеден перед снеговиком',5:'Возмущение уже высказано'},'Попросить кусок у снеговика; дальнейшая реакция зависит также от наличия предмета 16.'),
60:('Покупки Доброженого в Сноудине','Знакомство устанавливает 1, покупка прибавляет 15. При >0 продавец выглядит счастливым; с 5 убирается длинное вступление. В эпилоге ответы различаются при >10 и >40. Это накопленная отметка покупок, не количество штук напрямую.',{0:'Не познакомились',1:'Знакомство состоялось',16:'Одна покупка после знакомства',31:'Две покупки',46:'Больше двух покупок'},'Поговорить с продавцом и покупать Доброженое за 15 G.'),
70:('Порядок первых случайных встреч Сноудина','0 принуждает группу боя 30, 1 — 32. При 2 до plot=42 выбирает между ними; с plot>=42 (или murderlv>=2) назначает группу 24 и пишет 4. Дальше вступительная последовательность не навязывается.',{0:'Первая группа 30',1:'Вторая группа 32',2:'Ожидание условия группы 24',4:'Вступительная последовательность исчерпана'},'Проходить первые случайные встречи в лесу. Сам флаг бой не запускает.'),
72:('Условия ночлега в гостинице Сноудина','0 — первое предложение за 80 G. Если денег меньше 80, хозяйка разрешает бесплатно и пишет 2. При платной ветке пишет 1, а после короткого сна возвращает деньги. 2 открывает повторное бесплатное приглашение.',{0:'Первое посещение',1:'Платная ветка/возврат оплаты',2:'Бесплатный ночлег разрешён'},'Попросить комнату у хозяйки. Изменение флага не списывает и не возвращает золото.'),
79:('Знакомство с продавцом Доброженого в Водопадье','Первое завершение его вводного разговора в комнате магазина пишет 8. При >0 используется счастливый спрайт; при 0 звучит первое вступление. Не количество карточек — они являются отдельными предметами/флагами.',{0:'Первое знакомство ещё впереди',8:'Вступление завершено'},'Поговорить с продавцом в Водопадье.'),
84:('Разговоры с отшельником о внешнем мире','Отслеживает несколько ответов улиточного NPC: <2 — первая просьба, 2 — услышан рассказ, 3 — последующий вопрос; после ответа на поздний вопрос 4 означает воодушевление, 5 — просьбу уйти. Это состояние диалога, не открытие пути.',{0:'Начальное знакомство',2:'Первый рассказ выслушан',3:'Поздний вопрос',4:'Воодушевлённый ответ',5:'Просит уйти'},'Разговаривать с отшельником в Водопадье и отвечать на его вопросы.'),
90:('Разговор Монстрёнка про зонт','0 — первая встреча под дождём. Без зонта (flag[85]=0) становится 1, с зонтом — 2. После 2, если прийти без зонта, записывает 3 и замечание об исчезнувшем зонте. Зонт этот флаг не выдаёт.',{0:'Разговора ещё нет',1:'Встретились без зонта',2:'Встретились с зонтом',3:'Зонт исчез после разговора'},'Подойти к Монстрёнку у дождливого участка, взять/вернуть настоящий зонт.'),
91:('Сопровождение Монстрёнка через Водопадье','Координирует актёра между соседними постановочными комнатами. 1 — первая сцена завершена; 3 — остановка у эхоцветка; 4 — триггер следующего разговора; 6 — актёр побежал к сцене; 10 ставится вместе с plot=113 после завершения цепочки. Смена числа без актёров не проигрывает эти сцены.',{0:'Сопровождение не началось',1:'Начальная сцена завершена',3:'Остановка у эхоцветка',4:'Следующий разговор запущен',6:'Бег к сцене',10:'Цепочка завершена; plot=113'},'Идти вместе с Монстрёнком через соответствующие комнаты, не перепрыгивая локальные триггеры.'),
92:('Служебная дверь и ключ у стола','obj_stable открывает первую фазу при >0, а при >3 убирает блокирующий объект. Other_11 пишет 1; черновые текстовые варианты пишут 2; поиск ключа в obj_undynetrash — 3; Other_12 — 4. Эти объекты содержат черновые реплики «x»; это не универсальный ключ ко всем дверям Андайн.',{0:'Закрыто',1:'Первая фаза открытия',2:'Черновой диалог пройден',3:'Ключ из мусорного ведра взят',4:'Проход разблокирован'},'Задействуется только сценариями obj_stable/obj_undynetrash; изменение не создаёт эти объекты в текущей комнате.'),
93:('Визит домой к Напстаблуку','После приглашения пишет 1; после совместной сцены отдыха — 3. Отказ в соответствующем диалоге пишет 9 и переводит хозяина в уход (con=80). Холодильник при >=2 отвечает без повторного вступления; 9 даёт расстроенный ответ.',{0:'Первый визит',1:'Приглашение выслушано',3:'Совместный отдых пройден',9:'Отказ и расстроенный хозяин'},'Посетить Напстаблука дома и отвечать в сценах с едой и отдыхом.'),
}
